import sys
import json
import numpy as np
import pandas as pd

def to_float(x, nd=2):
    return round(float(x), nd)

def main():
    df = pd.read_csv(sys.argv[1])

    facts = []

    # ---- TOTAL level facts ----
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True)
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(total_rev_tw),
        "formula": "sum(Revenue_TW) across all entities"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(total_rev_lw),
        "formula": "sum(Revenue_LW) across all entities"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": to_float(total_rev_ly),
        "formula": "sum(Revenue_LY) across all entities"
    })

    if total_rev_lw and not np.isnan(total_rev_lw) and total_rev_lw != 0:
        total_wow = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(total_wow, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if total_rev_ly and not np.isnan(total_rev_ly) and total_rev_ly != 0:
        total_yoy = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(total_yoy, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(total_units_tw),
        "formula": "sum(Units_TW) across all entities"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(total_units_lw),
        "formula": "sum(Units_LW) across all entities"
    })

    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(total_orders_tw),
        "formula": "sum(Orders_TW) across all entities"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(total_orders_lw),
        "formula": "sum(Orders_LW) across all entities"
    })

    # ---- Top 3 entities by Revenue_TW: revenue + share ----
    top_rev = df.dropna(subset=['Revenue_TW']).nlargest(3, 'Revenue_TW')
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": to_float(row['Revenue_TW']),
            "formula": "Revenue_TW for entity"
        })
        if pd.notna(row.get('Share_Pct', np.nan)):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": to_float(row['Share_Pct'], 1),
                "formula": "Share_Pct for entity (Revenue_TW / total Revenue_TW * 100)"
            })

    # ---- Top 2 WoW gainers and decliners ----
    wow_df = df.dropna(subset=['WoW_Pct'])
    top_wow_gain = wow_df.nlargest(2, 'WoW_Pct')
    top_wow_loss = wow_df.nsmallest(2, 'WoW_Pct')
    for _, row in top_wow_gain.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })
    for _, row in top_wow_loss.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- Top 2 YoY gainers and decliners ----
    yoy_df = df.dropna(subset=['YoY_Pct'])
    top_yoy_gain = yoy_df.nlargest(2, 'YoY_Pct')
    top_yoy_loss = yoy_df.nsmallest(2, 'YoY_Pct')
    for _, row in top_yoy_gain.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(row['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })
    for _, row in top_yoy_loss.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(row['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Cap to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
